{
  "name": "json-path-query-engine",
  "version": "1.0.0",
  "description": "CLI query engine over a product catalog with nested JSON attributes, backed by Sequelize + SQLite.",
  "main": "cli.js",
  "private": true,
  "scripts": {
    "start": "node cli.js"
  },
  "dependencies": {
    "sequelize": "^6.37.3",
    "sqlite3": "^5.1.7"
  }
}

"use strict";

const fs = require("fs");
const path = require("path");
const { Sequelize, DataTypes } = require("sequelize");

/**
 * Strips Sequelize's "Executing (default): " style prefix from a log line,
 * leaving just the raw SQL statement.
 */
function cleanSqlLine(message) {
  return String(message).replace(/^Executing \([^)]*\):\s*/, "");
}

/**
 * Builds a logging function for Sequelize that appends every executed SQL
 * statement (one per line, in execution order) to the file referenced by
 * the SQL_LOG environment variable, if set.
 */
function createLogger() {
  const sqlLogPath = process.env.SQL_LOG;
  if (!sqlLogPath) {
    return false;
  }
  return (message) => {
    const line = cleanSqlLine(message);
    fs.appendFileSync(sqlLogPath, line + "\n");
  };
}

/**
 * Creates a Sequelize instance pointed at the given SQLite file.
 */
function createSequelize(dbPath) {
  const storage = path.resolve(process.cwd(), dbPath);
  return new Sequelize({
    dialect: "sqlite",
    storage,
    logging: createLogger(),
  });
}

/**
 * Defines (without syncing) the Product model on the given Sequelize
 * instance.
 */
function defineProduct(sequelize) {
  return sequelize.define(
    "Product",
    {
      id: {
        type: DataTypes.INTEGER,
        autoIncrement: true,
        primaryKey: true,
      },
      name: {
        type: DataTypes.STRING,
        allowNull: false,
      },
      attributes: {
        type: DataTypes.JSON,
        allowNull: false,
        defaultValue: {},
      },
    },
    {
      tableName: "Products",
      timestamps: false,
    }
  );
}

module.exports = { createSequelize, defineProduct };

"use strict";

/**
 * Converts a dot-separated path (e.g. "specs.ram") into a SQLite JSON path
 * expression (e.g. $."specs"."ram"). Each segment is individually quoted so
 * that keys containing unusual characters (spaces, dashes, etc.) still
 * produce a valid path.
 */
function toJsonPath(dotPath) {
  if (!dotPath || dotPath.length === 0) {
    return "$";
  }
  const segments = dotPath.split(".");
  const quoted = segments
    .map((segment) => `."${segment.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`)
    .join("");
  return `$${quoted}`;
}

module.exports = { toJsonPath };

"use strict";

const fs = require("fs");
const { QueryTypes } = require("sequelize");
const { toJsonPath } = require("./jsonPath");

const NUMERIC_OPS = {
  eq: "=",
  gt: ">",
  gte: ">=",
  lt: "<",
  lte: "<=",
};

/**
 * Normalizes a raw row returned by a raw SQL query into the output shape
 * { id, name, attributes }.
 */
function rowToProduct(row) {
  let attributes = row.attributes;
  if (typeof attributes === "string") {
    attributes = JSON.parse(attributes);
  }
  return {
    id: Number(row.id),
    name: row.name,
    attributes,
  };
}

/**
 * Replaces the entire Products table with the products found in the given
 * JSON file. Products are inserted in array order so the first element
 * receives id 1.
 */
async function loadProducts(sequelize, Product, filePath) {
  const raw = fs.readFileSync(filePath, "utf-8");
  const data = JSON.parse(raw);
  if (!Array.isArray(data)) {
    throw new Error("Input file must contain a JSON array of products.");
  }

  await sequelize.sync({ force: true });

  for (const item of data) {
    await Product.create({
      name: item.name,
      attributes: item.attributes || {},
    });
  }
}

/**
 * Filters products whose numeric value at attributes.<dotPath> satisfies
 * the given comparison operator against value. Uses json_extract so that
 * SQLite returns a properly typed (numeric) value, ensuring numeric rather
 * than lexicographic comparison semantics.
 */
async function filterNum(sequelize, dotPath, op, value) {
  const sqlOp = NUMERIC_OPS[op];
  if (!sqlOp) {
    throw new Error(`Invalid numeric operator: ${op}`);
  }
  const jsonPath = toJsonPath(dotPath);
  const numericValue = Number(value);
  if (Number.isNaN(numericValue)) {
    throw new Error(`Invalid numeric value: ${value}`);
  }

  const sql =
    `SELECT id, name, attributes FROM Products ` +
    `WHERE typeof(json_extract(attributes, :jsonPath)) IN ('integer', 'real') ` +
    `AND json_extract(attributes, :jsonPath) ${sqlOp} :value ` +
    `ORDER BY id ASC`;

  const rows = await sequelize.query(sql, {
    replacements: { jsonPath, value: numericValue },
    type: QueryTypes.SELECT,
  });

  return rows.map(rowToProduct);
}

/**
 * Filters products whose string value at attributes.<dotPath> is exactly
 * equal to value.
 */
async function filterStr(sequelize, dotPath, value) {
  const jsonPath = toJsonPath(dotPath);

  const sql =
    `SELECT id, name, attributes FROM Products ` +
    `WHERE typeof(json_extract(attributes, :jsonPath)) = 'text' ` +
    `AND json_extract(attributes, :jsonPath) = :value ` +
    `ORDER BY id ASC`;

  const rows = await sequelize.query(sql, {
    replacements: { jsonPath, value: String(value) },
    type: QueryTypes.SELECT,
  });

  return rows.map(rowToProduct);
}

/**
 * Filters products for which the JSON array located at
 * attributes.<dotPath> contains an element exactly equal to value.
 * Uses json_each as a correlated table-valued function so the match is
 * performed on individual array elements (never as a substring match on
 * the serialized document).
 */
async function filterTag(sequelize, dotPath, value) {
  const jsonPath = toJsonPath(dotPath);

  const sql =
    `SELECT id, name, attributes FROM Products AS p ` +
    `WHERE EXISTS (` +
    `  SELECT 1 FROM json_each(p.attributes, :jsonPath) AS je ` +
    `  WHERE je.value = :value` +
    `) ORDER BY p.id ASC`;

  const rows = await sequelize.query(sql, {
    replacements: { jsonPath, value: String(value) },
    type: QueryTypes.SELECT,
  });

  return rows.map(rowToProduct);
}

/**
 * Sets the nested key at attributes.<dotPath> for the product with the
 * given id, preserving every other key/branch of the document. Returns the
 * updated product, or null if no product with that id exists.
 */
async function setKey(sequelize, id, dotPath, jsonLiteral) {
  const existing = await sequelize.query(
    `SELECT id FROM Products WHERE id = :id`,
    { replacements: { id }, type: QueryTypes.SELECT }
  );
  if (existing.length === 0) {
    return null;
  }

  const jsonPath = toJsonPath(dotPath);

  await sequelize.query(
    `UPDATE Products SET attributes = json_set(attributes, :jsonPath, json(:jsonLiteral)) WHERE id = :id`,
    {
      replacements: { jsonPath, jsonLiteral, id },
      type: QueryTypes.UPDATE,
    }
  );

  const rows = await sequelize.query(
    `SELECT id, name, attributes FROM Products WHERE id = :id`,
    { replacements: { id }, type: QueryTypes.SELECT }
  );

  return rowToProduct(rows[0]);
}

module.exports = {
  loadProducts,
  filterNum,
  filterStr,
  filterTag,
  setKey,
};

#!/usr/bin/env node
"use strict";

const { createSequelize, defineProduct } = require("./lib/db");
const { loadProducts, filterNum, filterStr, filterTag, setKey } = require("./lib/queries");

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token.startsWith("--")) {
      const key = token.slice(2);
      const next = argv[i + 1];
      if (next === undefined || next.startsWith("--")) {
        args[key] = true;
      } else {
        args[key] = next;
        i++;
      }
    }
  }
  return args;
}

function requireArg(args, name, command) {
  if (args[name] === undefined) {
    throw new Error(`Missing required --${name} option for command "${command}".`);
  }
  return args[name];
}

function printJson(value) {
  process.stdout.write(JSON.stringify(value, null, 2) + "\n");
}

async function main() {
  const [, , command, ...rest] = process.argv;
  const args = parseArgs(rest);
  const dbPath = args.db || "./data.sqlite";

  if (!command) {
    throw new Error(
      "Usage: node cli.js <load|filter-num|filter-str|filter-tag|set-key> --db <path> [options]"
    );
  }

  const sequelize = createSequelize(dbPath);
  const Product = defineProduct(sequelize);

  try {
    switch (command) {
      case "load": {
        const file = requireArg(args, "file", command);
        await loadProducts(sequelize, Product, file);
        break;
      }

      case "filter-num": {
        const dotPath = requireArg(args, "path", command);
        const op = requireArg(args, "op", command);
        const value = requireArg(args, "value", command);
        const results = await filterNum(sequelize, dotPath, op, value);
        printJson(results);
        break;
      }

      case "filter-str": {
        const dotPath = requireArg(args, "path", command);
        const value = requireArg(args, "value", command);
        const results = await filterStr(sequelize, dotPath, value);
        printJson(results);
        break;
      }

      case "filter-tag": {
        const dotPath = requireArg(args, "path", command);
        const value = requireArg(args, "value", command);
        const results = await filterTag(sequelize, dotPath, value);
        printJson(results);
        break;
      }

      case "set-key": {
        const id = requireArg(args, "id", command);
        const dotPath = requireArg(args, "path", command);
        const jsonLiteral = requireArg(args, "json", command);
        const updated = await setKey(sequelize, Number(id), dotPath, jsonLiteral);
        if (!updated) {
          throw new Error(`No product found with id ${id}.`);
        }
        printJson(updated);
        break;
      }

      default:
        throw new Error(`Unknown command: ${command}`);
    }
  } finally {
    await sequelize.close();
  }
}

main().then(
  () => process.exit(0),
  (err) => {
    process.stderr.write(`Error: ${err.message}\n`);
    process.exit(1);
  }
);

